using System;using System.IO;using System.Linq;using System.Windows.Forms;namespace Mapping{    /// <summary>    ///     /// </summary>    public class TechsenseConverter : MapConverterSkeleton    {        /// <summary>        ///         /// </summary>        public TechsenseConverter()        {        }        /// <summary>        ///         /// </summary>        /// <param name="fileName"></param>        /// <returns></returns>        public override MapData Read(string fileName, bool isOriginalMap = false)        {            var mapData = new MapData();            string url = string.Format("{0}", fileName);            FileStream fs = new FileStream(url, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);            StreamReader sr = new StreamReader(fs);            try            {                string[] content = sr.ReadToEnd().Replace("\r\n", "^").Split('^');                if (content.Count() != 0)                {                    mapData.SubstrateID = content[3];//3                    mapData.NullBin = Bin.CreateNullBin(content[5].ToCharArray()[0]);//5                    var emptyBin = content[7].ToCharArray();//7                    if (emptyBin.Count() > 0)                    {                        mapData.EmptyBin = Bin.CreateEmptyBin(emptyBin[0]);                    }                    //if (mapSaveType == MapSaveType.Wafer_WaferMap_MPW || mapSaveType == MapSaveType.Wafer_WaferMap_SPW)                    //{                    //    mapData.EmptyBin.Work = false;                    //    string[] bins = content[9].Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);//9                    //    mapData.Bins = new BinCollection();                    //    foreach (var b in bins)                    //    {                    //        string[] bs = b.Split(new char[] { '|' }, StringSplitOptions.RemoveEmptyEntries);                    //        string[] str = bs[0].Split(new char[] { ' ', '-' }, StringSplitOptions.RemoveEmptyEntries);                    //        Bin bin = new Bin(str[0][0], true);                    //        if (str.Count() > 1)                    //        {                    //            bin.Description = str[1].Trim();                    //        }                    //        bin.Color = System.Drawing.Color.FromArgb(int.Parse(bs[1]), int.Parse(bs[2]), int.Parse(bs[3]), int.Parse(bs[4]));                    //        bool work = false;                    //        Boolean.TryParse(bs[5], out work);                    //        bin.Work = work;                    //        mapData.Bins.Add(bin);                    //    }                    //}                    //else if (mapSaveType == MapSaveType.Tray_WaferMap)                    //{                    //    mapData.EmptyBin.Work = true;                    //    mapData.Bins = new BinCollection();                    //}                    int brs, bcs;                    int.TryParse(content[11], out brs);//11                    int.TryParse(content[13], out bcs);//13                    mapData.BlockRows = brs;                    mapData.BlockColumns = bcs;                    int rs, cs;                    int.TryParse(content[15], out rs);//15                    int.TryParse(content[17], out cs);//17                    mapData.Rows = rs;                    mapData.Columns = cs;                    string[] shotBin = content[19].Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);//19                    if (shotBin.Count() > 0)                    {                        mapData.ShotBins = new Bin[mapData.Rows, mapData.Columns];                        for (int i = 0; i < shotBin.Count(); i++)                        {                            int r = i / mapData.Columns;                            int c = i - r * mapData.Columns;                            mapData.ShotBins[r, c] = mapData.Bins[shotBin[i].ToCharArray()[0]];                        }                    }                    mapData.BinCodes = new BinCode[mapData.BlockRows, mapData.BlockColumns, mapData.Rows, mapData.Columns];                    int index = 21;//21                    for (int br = 0; br < mapData.BlockRows; br++)                    {                        for (int bc = 0; bc < mapData.BlockColumns; bc++)                        {                            for (int r = 0; r < mapData.Rows; r++)                            {                                if (content[index] != "")                                {                                    var binCodes = content[index].ToCharArray();                                    var binCodesList = binCodes.ToList<char>();                                    binCodesList.RemoveAll(o => { return o == ','; });                                    for (int c = 0; c < mapData.Columns; c++)                                    {                                        mapData.BinCodes[br, bc, r, c] = binCodesList[c];                                    }                                }                                index++;                            }                        }                    }                }            }            catch            {                MessageBox.Show("사전 지도 형식. 파일 불일치 !");            }            return mapData;        }    }}